// Generated by Suite Builder from a crawl of the site. How Cypress runs the suite.
// EDIT RULES: edit only inside YOURS blocks; regenerating keeps them and rewrites the rest of this file.
import { appendFileSync, existsSync, mkdirSync, readdirSync, readFileSync, renameSync, rmSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { defineConfig } from 'cypress';

/**
 * A run stops early when its tests keep failing the same way: after stopAfter tests in a row fail
 * for the same reason (the site is down, a wall the suite cannot pass), the tests left are skipped,
 * saying why. Two reasons are the same when they differ only in what they name: an address, a
 * quoted text, a number. A test that passes starts the count again. Kept here, in Node, because
 * each spec runs in a fresh browser.
 */
const stopEarly = { lastWay: '', inARow: 0, stopped: '' };

/** What a failure says when the site could not be reached at all: every such failure is one way. */
const UNREACHABLE = /ETIMEDOUT|ECONNREFUSED|ECONNRESET|ENOTFOUND|EAI_AGAIN|EHOSTUNREACH|ENETUNREACH|ERR_CONNECTION_|ERR_NAME_NOT_RESOLVED|ERR_ADDRESS_UNREACHABLE|ERR_INTERNET_DISCONNECTED|ERR_TIMED_OUT|ConnectException|UnknownHostException|HttpConnectTimeoutException|The site cannot be reached/;
/** What a page that did not load in time is said with, in every framework: one way, so a run on a site too slow to answer stops early. */
const SLOW = /ms exceeded|Timed out receiving message from renderer|\) timed out after|for your remote page to load/;

/**
 * The specs in the order a run takes them (G-126): the link report first, so a site that cannot be
 * reached stops the run in seconds; the site's other specs; the suite's tests of itself last. A
 * pattern ('cypress/e2e/**') runs in the order the folder is read, which put the harness first (Site
 * G's run, 2026-10-03); a list of files is given in this order. Read as each run starts, so a story
 * spec added since is in it.
 */
function specsInOrder(): string[] {
  const all: string[] = [];
  const walk = (dir: string) => {
    for (const entry of readdirSync(dir, { withFileTypes: true }).sort((a, b) => a.name.localeCompare(b.name))) {
      if (entry.isDirectory()) walk(`${dir}/${entry.name}`);
      else if (entry.name.endsWith('.cy.ts')) all.push(`${dir}/${entry.name}`);
    }
  };
  if (existsSync('cypress/e2e')) walk('cypress/e2e');
  const first: string = 'cypress/e2e/cases/links.cy.ts';
  const last: string = 'cypress/e2e/harness.cy.ts';
  return [...all.filter((s) => s === first), ...all.filter((s) => s !== first && s !== last), ...all.filter((s) => s === last)];
}

/**
 * Page timings, in every run: each page a test reached, a row in cypress/timings/timings.csv (the
 * same columns as the Java suites'); at the end of the run the slowest pages, and any flagged slow:
 * much longer after its load event than the crawl saw (3 times, and 1000
 * ms more), ready much later than in the previous run (cypress/timings-previous/), or ready past
 * 50% of its time limit (pageLoadTimeout): it passed, and a slower day fails it. Not load
 * testing: one visitor, as the tests go.
 */
const TIMING_COLUMNS = 'test,page,path,ready_ms,first_byte_ms,dom_loaded_ms,load_ms,after_load_ms,crawl_after_load_ms,slow';

/** What a run's results hold that its report shows. */
type RunResults = { runs?: { spec: { name: string }; tests: { title: string[]; state: string; duration?: number; displayError?: string | null }[] }[] };

/** The spec each kind of test is in (G-126's tags): the report's first column. */
const KIND_OF_SPEC: Record<string, string> = { 'links.cy.ts': 'http', 'smoke.cy.ts': 'smoke', 'navigation.cy.ts': 'navigation', 'menus.cy.ts': 'menus', 'site.cy.ts': 'site', 'harness.cy.ts': 'harness' };
const escape = (text: string) => text.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

/** Every role a test may sign in as (pages/signin/SignIns.ts): each has its secrets/<role>.login, written blank when missing (G-159). */
const ROLES = ['user','admin'];
const BLANK_ACCOUNT = 'Username:\nPassword:\n';

/** A file's account, when both its values are filled in (Username: and Password:, each everything after the first colon). */
function accountIn(file: string): { username: string; password: string; from: string } | null {
  if (!existsSync(file)) return null;
  const found: Record<string, string> = {};
  for (const line of readFileSync(file, 'utf8').split(/\r?\n/)) {
    const colon = line.indexOf(':');
    if (colon > 0) found[line.slice(0, colon).trim().toLowerCase()] = line.slice(colon + 1).trim();
  }
  return found.username && found.password ? { username: found.username, password: found.password, from: file } : null;
}

/**
 * The role's account (G-159), in this order: the environment (SUITE_USER_USERNAME and SUITE_USER_PASSWORD;
 * SUITE_ADMIN_... for admin); docked (this suite in Suite Builder's dock), Suite Builder's own store, in
 * Suite Builder's folder (the dock's DOCK.md names it, G-163): <site>/<role>.login; else this suite's
 * secrets/<role>.login. None: what to fill in.
 */
function storeFolder(): string | null {
  if (process.env.SUITE_BUILDER_SECRETS) return process.env.SUITE_BUILDER_SECRETS;
  if (!existsSync(join('..', 'DOCK.md'))) return null;
  const line = readFileSync(join('..', 'DOCK.md'), 'utf8').split(/\r?\n/).find((l) => l.startsWith('Accounts: '));
  return line ? line.slice('Accounts: '.length).trim() : null;
}
function accountFor(role: string): { username: string; password: string; from: string } | { missing: string } {
  const r = role.toUpperCase().replace(/[^A-Z0-9]/g, '_');
  const [user, pass] = [process.env[`SUITE_${r}_USERNAME`]?.trim(), process.env[`SUITE_${r}_PASSWORD`]?.trim()];
  if (user && pass) return { username: user, password: pass, from: `SUITE_${r}_USERNAME and SUITE_${r}_PASSWORD` };
  const folder = storeFolder();
  const store = folder ? join(folder, new URL('https://the-internet.herokuapp.com').hostname.replace(/^www\./, ''), `${role}.login`) : null;
  const found = (store ? accountIn(store) : null) ?? accountIn(join('secrets', `${role}.login`));
  return found ?? { missing: `This test signs in as ${role}: fill in secrets/${role}.login (Username: and Password:), or set SUITE_${r}_USERNAME and SUITE_${r}_PASSWORD${store ? `, or fill in Suite Builder's ${store}` : ''}. Never write an account into the code.` };
}

/** One row of a test data file (core/TestData.ts): its fields by the header's names, and where it is. */
type Row = { file: string; line: number; fields: Record<string, string> };

/**
 * The team's test data (G-154), read here so every spec of a run shares one queue per file: the
 * environment's copy first (cypress/data/<environment>/), else the shared one. A line starting with #
 * is a note; a field with a comma or a quote is in quotes, its quotes doubled.
 */
const testData = { environment: '', queues: new Map<string, { rows: Row[]; size: number }>() };
function dataFile(file: string): string {
  const own = testData.environment ? `cypress/data/${testData.environment}/${file}` : `cypress/data/${file}`;
  if (existsSync(own)) return own;
  if (existsSync(`cypress/data/${file}`)) return `cypress/data/${file}`;
  throw new Error(`No test data ${file}: looked for ${own}${own === `cypress/data/${file}` ? '' : ` and cypress/data/${file}`}. Add it, a header row first (cypress/data/README.md).`);
}
function dataRows(path: string): Row[] {
  const cells = (line: string) => [...line.matchAll(/(?:^|,)\s*(?:"((?:[^"]|"")*)"|([^,]*))/g)].map((m) => (m[1] !== undefined ? m[1].replace(/""/g, '"') : (m[2] ?? '')).trim());
  let header: string[] | null = null;
  const rows: Row[] = [];
  readFileSync(path, 'utf8').split(/\r?\n/).forEach((line, i) => {
    if (!line.trim() || line.startsWith('#')) return;
    const values = cells(line);
    if (!header) {
      header = values;
      return;
    }
    if (values.length !== header.length) throw new Error(`${path}, line ${i + 1}: ${values.length} fields, where the header has ${header.length}`);
    rows.push({ file: path.split('/').pop() ?? path, line: i + 1, fields: Object.fromEntries(header.map((name, c) => [name, values[c]])) });
  });
  return rows;
}

/** Why each test skipped (Checks.assume) was skipped, by its spec's file name and its title. */
const skips = new Map<string, string>();
const fileOf = (spec: string) => spec.split('/').pop() ?? '';

/** cypress/report.html (G-130): every test, its kind, how it went and why, and the failures' evidence (cypress/failures/); failures first. */
function writeReport(results: RunResults, used: string): void {
  const rows = (results.runs ?? []).flatMap((run) =>
    run.tests.map((t) => {
      const skipped = skips.get(`${fileOf(run.spec.name)}\n${t.title.join(' > ')}`);
      const state = t.state === 'pending' && skipped !== undefined ? 'skipped' : t.state;
      return { kind: KIND_OF_SPEC[fileOf(run.spec.name)] ?? 'stories', where: `${run.spec.name} > ${t.title.join(' > ')}`, state, ms: t.duration ?? 0, why: skipped ?? (t.displayError ?? '').split('\n')[0] };
    }),
  );
  rows.sort((a, b) => Number(b.state === 'failed') - Number(a.state === 'failed'));
  const kinds = new Map<string, [number, number, number]>();
  for (const r of rows) {
    const [passed, run, skipped] = kinds.get(r.kind) ?? [0, 0, 0];
    kinds.set(r.kind, [passed + Number(r.state === 'passed'), run + 1, skipped + Number(r.state === 'skipped')]);
  }
  const html = `<!doctype html><meta charset=utf-8><title>Test run</title><style>body{font:14px system-ui;margin:2em}td,th{padding:.3em .6em;text-align:left;border-bottom:1px solid #ddd}.failed{color:#b00}.pending,.skipped{color:#888}</style>
<h1>Test run, ${new Date().toISOString().slice(0, 19).replace('T', ' ')}</h1><h2>By kind</h2><table>${[...kinds].map(([k, [p, n, s]]) => `<tr><td>${k}<td>${p} of ${n} passed${s ? ` (${s} skipped)` : ''}`).join('')}</table>
<h2>Tests</h2><p>A failed test's evidence: <a href="failures/">failures/</a>.</p><table><tr><th>Kind<th>Test<th>How<th>ms<th>Why${rows.map((r) => `<tr class=${r.state}><td>${r.kind}<td>${escape(r.where)}<td>${r.state}<td>${r.ms}<td>${escape(r.why)}`).join('')}</table>${used ? `<h2>Test data used up</h2><p>${escape(used)}` : ''}
`;
  writeFileSync('cypress/report.html', html);
  console.log(`The run's report: cypress/report.html`);
}
const TIMINGS = 'cypress/timings/timings.csv';
const TIMINGS_BEFORE = 'cypress/timings-previous/timings.csv';
const timings: { rows: string[][]; before: Map<string, number>; last: string | null } = { rows: [], before: new Map(), last: null };
const csvLine = (cells: string[]) => cells.map((c) => `"${c.replace(/"/g, '""')}"`).join(',');
const csvCells = (line: string) => [...line.matchAll(/"((?:[^"]|"")*)"/g)].map((m) => m[1].replace(/""/g, '"'));

/** The row of one page reached; the budget's failure, or null. */
function pageTiming(r: { test: string; page: string; path: string; times: string; crawlSettledMs: number; budget: string; limit: number }): string | null {
  const t = r.times.split(',');
  if (t.length < 4) return null;
  // The same navigation and page again (open(), then verify().isLoaded()): one row. A single-page app's next page shares the navigation, not the path.
  const seen = t.length > 4 ? `${r.test}\n${t[4]} ${r.path}` : null;
  if (seen !== null && seen === timings.last) return null;
  // A single-page app's route change (the same navigation, another path): its times count from the page it was reached from, so it is never judged against a load event.
  const routed = seen !== null && timings.last !== null && timings.last.startsWith(`${r.test}\n${t[4]} `);
  timings.last = seen;
  const [ready, load] = [Number(t[0]), Number(t[3])];
  const afterLoad = load > 0 ? Math.max(0, ready - load) : 0;
  const slow: string[] = [];
  if (!routed && r.crawlSettledMs >= 0 && afterLoad > r.crawlSettledMs * 3 && afterLoad - r.crawlSettledMs > 1000) slow.push(`${afterLoad} ms after its load event, where the crawl saw ${r.crawlSettledMs} ms for its type`);
  const earlier = timings.before.get(`${r.test}\n${r.path}`);
  if (earlier !== undefined && ready > earlier * 3 && ready - earlier > 1000) slow.push(`ready in ${ready} ms, where the previous run took ${earlier} ms`);
  if (!routed && ready > r.limit * 0.5) slow.push(`ready in ${ready} ms, ${Math.round((ready * 100) / r.limit)}% of its time limit (${r.limit} ms, pageLoadTimeout): it passed, and a slower day fails it`);
  const row = [r.test, r.page, r.path, t[0], t[1], t[2], t[3], String(afterLoad), r.crawlSettledMs < 0 ? '' : String(r.crawlSettledMs), slow.join('; ')];
  timings.rows.push(row);
  // cypress open has no before:run: the file starts here then.
  if (!existsSync(TIMINGS)) {
    mkdirSync('cypress/timings', { recursive: true });
    writeFileSync(TIMINGS, `${TIMING_COLUMNS}\n`);
  }
  appendFileSync(TIMINGS, `${csvLine(row)}\n`);
  return r.budget && ready > Number(r.budget) * 1000 ? `${r.page} took ${ready} ms to be ready at ${r.path}, over the budget of ${r.budget} s (--expose loadBudget)` : null;
}
const wayOf = (reason: string) => (UNREACHABLE.test(reason) ? 'the site cannot be reached' : SLOW.test(reason) ? 'a page did not load in time' : reason).replace(/"[^"]*"|'[^']*'/g, '""').replace(/(https?:)?\/\/\S+|\/\S*/g, '/').replace(/\d+/g, '0');

export default defineConfig({
  e2e: {
    // The crawled site, unless BASE_URL points elsewhere (a staging copy):
    // BASE_URL=https://staging.example.com npx cypress run
    baseUrl: process.env.BASE_URL || 'https://the-internet.herokuapp.com',
    specPattern: specsInOrder(),
    supportFile: 'cypress/support/e2e.ts',
    viewportWidth: 1440,
    viewportHeight: 900,
    // Fail within seconds rather than minutes: 10 s for a click or a check, 30 s for a page.
    defaultCommandTimeout: 10000,
    pageLoadTimeout: 30000,
    // The browser name the crawl used: the site answered it.
    userAgent: process.env.USER_AGENT || 'Mozilla/5.0 (compatible; SuiteBuilder/1.0; +https://github.com/ghost-in-the-kernel/suite-builder)',
    video: false,
    // The failure's screenshot is taken by the suite (support/e2e.ts), under a name short enough for Windows.
    screenshotOnRunFailure: false,
    // Links that go to another site are followed there (Cypress would stop at the site's edge).
    chromeWebSecurity: false,
    setupNodeEvents(on, config) {
      // Steps, in plain English, printed to the terminal as they happen.
      on('task', {
        suiteLog(message: string) {
          console.log(message);
          return null;
        },
        testFailed({ reason, stopAfter, spec }: { reason: string; stopAfter: number; spec: string }) {
          const way = wayOf(reason);
          // The link report runs first: when it could not reach the site at all, the run stops at once.
          if (spec === 'links.cy.ts' && way === 'the site cannot be reached' && stopAfter > 0 && !stopEarly.stopped) {
            stopEarly.stopped = `the link report could not reach the site (${reason})`;
            console.log(`\n   STOPPING EARLY: ${stopEarly.stopped}.\n   The tests left are skipped; fix that first, then run again. (--expose stopAfter=0 runs every test whatever happens.)\n`);
            return null;
          }
          stopEarly.inARow = way === stopEarly.lastWay ? stopEarly.inARow + 1 : 1;
          stopEarly.lastWay = way;
          if (stopAfter > 0 && stopEarly.inARow >= stopAfter && !stopEarly.stopped) {
            stopEarly.stopped = `${stopEarly.inARow} tests in a row failed the same way (${reason})`;
            console.log(`\n   STOPPING EARLY: ${stopEarly.stopped}.\n   The tests left are skipped; fix that first, then run again. (--expose stopAfter=0 runs every test whatever happens.)\n`);
          }
          return null;
        },
        // A role's account, for core/SignIn.ts; never logged (G-159).
        account(role: string) {
          return accountFor(role);
        },
        testDataRows(file: string) {
          return dataRows(dataFile(file));
        },
        // A consumable row: the next one no test of this run has taken (core/TestData.ts).
        testDataTake(file: string) {
          const path = dataFile(file);
          if (!testData.queues.has(path)) {
            const rows = dataRows(path);
            testData.queues.set(path, { rows, size: rows.length });
          }
          const queue = testData.queues.get(path) ?? { rows: [], size: 0 };
          return { row: queue.rows.shift() ?? null, why: `no row left in ${path}: each row is used once a run, and all ${queue.size} were; add rows` };
        },
        // A test skipped by Checks.assume: why, for the report; a skip is no failure, and breaks no run of failures.
        testSkipped({ spec, title, why }: { spec: string; title: string; why: string }) {
          skips.set(`${fileOf(spec)}\n${title}`, why);
          console.log(`   SKIPPED: ${why}`);
          return null;
        },
        testPassed() {
          stopEarly.lastWay = '';
          stopEarly.inARow = 0;
          return null;
        },
        runStopped() {
          return stopEarly.stopped;
        },
        pageTiming,
      });
      // Each run starts clean: the last run's evidence and list of flaky tests go.
      on('before:run', (details) => {
        // The run's first line: the site, the browser, and every setting given with --expose (G-129).
        testData.environment = String(process.env.ENVIRONMENT || ((config as { expose?: Record<string, unknown> }).expose ?? {}).environment || '');
        const exposed = Object.entries((config as { expose?: Record<string, unknown> }).expose ?? {}).map(([name, value]) => `${name} ${String(value)} (--expose)`);
        // Where baseUrl came from: BASE_URL, the crawl's (the default), else --config or this file (Ghost's run, 2026-10-04).
        const baseFrom = process.env.BASE_URL ? 'BASE_URL' : config.baseUrl === 'https://the-internet.herokuapp.com' ? "the crawl's" : '--config or cypress.config.ts';
        console.log(`Settings: baseUrl ${config.baseUrl} (${baseFrom}), browser ${details.browser?.name ?? 'electron'}${[...(process.env.USER_AGENT ? [`, userAgent ${process.env.USER_AGENT} (USER_AGENT)`] : []), ...(process.env.ENVIRONMENT ? [`, environment ${process.env.ENVIRONMENT} (ENVIRONMENT)`] : []), ...exposed.map((e) => `, ${e}`)].join('')}; the rest as cypress.config.ts says.`);
        rmSync('cypress/failures', { recursive: true, force: true });
        // Every role's account file, blank, where there is none: a fresh clone shows where accounts go (G-159).
        mkdirSync('secrets', { recursive: true });
        for (const role of ROLES) if (!existsSync(join('secrets', `${role}.login`))) writeFileSync(join('secrets', `${role}.login`), BLANK_ACCOUNT);
        rmSync('cypress/flaky-tests.txt', { force: true });
        // The last run's timings become the previous run's: a page much slower than there is flagged.
        if (existsSync(TIMINGS)) {
          mkdirSync('cypress/timings-previous', { recursive: true });
          renameSync(TIMINGS, TIMINGS_BEFORE);
        }
        if (existsSync(TIMINGS_BEFORE)) {
          for (const line of readFileSync(TIMINGS_BEFORE, 'utf8').split('\n').slice(1).filter(Boolean)) {
            const c = csvCells(line);
            if (c[3]) timings.before.set(`${c[0]}\n${c[2]}`, Number(c[3]));
          }
        }
        mkdirSync('cypress/timings', { recursive: true });
        writeFileSync(TIMINGS, `${TIMING_COLUMNS}\n`);
      });
      on('after:run', (results) => {
        const used = [...testData.queues].map(([path, q]) => `${path} gave ${q.size - q.rows.length} of ${q.size} rows`).join('; ');
        if (used) console.log(`Test data used up: ${used}`);
        writeReport(results as unknown as RunResults, used);
        if (!timings.rows.length) return;
        const rows = [...timings.rows].sort((a, b) => Number(b[3]) - Number(a[3]));
        console.log(`\nPage timings (${TIMINGS}, ${rows.length} pages reached). The slowest:`);
        for (const r of rows.slice(0, 5)) console.log(`   ${r[3]} ms  ${r[1]} ${r[2]}`);
        for (const r of rows) if (r[9]) console.log(`   SLOW: ${r[1]} ${r[2]} (${r[0]}): ${r[9]}`);
      });
      // A generated test that failed once and passed on its second try (each generated spec's retries, G-128)
      // passes, and is listed as flaky: here and in cypress/flaky-tests.txt.
      on('after:spec', (spec, results) => {
        for (const test of results?.tests ?? []) {
          if (test.state !== 'passed' || test.attempts.length < 2) continue;
          const line = `${spec.name} > ${test.title.join(' > ')}: passed on its second try`;
          console.log(`   FLAKY: ${line}`);
          appendFileSync('cypress/flaky-tests.txt', `${new Date().toISOString().slice(0, 16).replace('T', ' ')}  ${line}\n`);
        }
      });
    },
    // ==== YOURS (settings): safe to edit; regenerating keeps what is between these lines ====
    // ==== END YOURS (settings) ====
  },
});
